<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $id=(int)($d['journey_id']??0); $j=$id>0?journeys_find($db,$id):null; if(!$j){ApiResponse::notFound('Journey not found.');exit;} if(!journeys_can_manage($db,$j,$uid)){ApiResponse::forbidden('Only owner can update journey.');exit;} $title=trim((string)($d['title']??'')); $desc=trim((string)($d['description']??'')); if($title===''||mb_strlen($title)>JOURNEY_TITLE_MAX){ApiResponse::validation(['title'=>'Valid title required.']);exit;} if(mb_strlen($desc)>JOURNEY_DESC_MAX){ApiResponse::validation(['description'=>'Description too long.']);exit;} [$start,$end]=journeys_validate_dates(trim((string)($d['start_date']??'')),trim((string)($d['end_date']??''))); $privacy=journeys_clean_privacy((string)($d['privacy_level']??$j['privacy_level'])); $status=journeys_clean_status((string)($d['status']??$j['status'])); $legacy=journeys_legacy_privacy($privacy); $s=$db->prepare('UPDATE journeys SET title=:title,description=:description,start_date=:start_date,end_date=:end_date,privacy_level=:privacy,status=:status WHERE id=:id'); $s->execute(['title'=>$title,'description'=>$desc?:null,'start_date'=>$start,'end_date'=>$end,'privacy'=>$legacy,'status'=>$status,'id'=>$id]); ApiResponse::success(['journey'=>journeys_format($db,journeys_find($db,$id))],'Journey updated.'); }catch(Throwable $e){Logger::error('Journey update failed',['error'=>$e->getMessage()]);ApiResponse::serverError($e instanceof InvalidArgumentException?$e->getMessage():'Unable to update journey.');}
?>
